describe('Error Message Screen Reader Accessibility', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should display error message with aria-live="polite" and be announced by screen reader', () => {
    // Attempt to submit form with invalid email
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="submit-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="email-error-message"]').should('be.visible');

    // Verify aria-live="polite" attribute is present
    cy.get('[data-testid="email-error-message"]').should('have.attr', 'aria-live', 'polite');

    // Verify error message contains descriptive text
    cy.get('[data-testid="email-error-message"]').should('contain', 'Please enter a valid email address');

    // Verify error message has role="alert" or similar for screen reader announcement
    cy.get('[data-testid="email-error-message"]').should('have.attr', 'role', 'alert');

    // Verify error message is associated with the input field
    cy.get('[data-testid="email-input"]').should('have.attr', 'aria-describedby', '[data-testid="email-error-message"]');

    // Verify error message is visible to screen reader
    cy.get('[data-testid="email-error-message"]').should('be.visible');
  });

  it('should handle multiple error messages and announce them correctly', () => {
    // Attempt to submit form with invalid email and password
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="password-input"]').type('short');
    cy.get('[data-testid="submit-button"]').click();

    // Verify both error messages appear
    cy.get('[data-testid="email-error-message"]').should('be.visible');
    cy.get('[data-testid="password-error-message"]').should('be.visible');

    // Verify both error messages have aria-live="polite"
    cy.get('[data-testid="email-error-message"]').should('have.attr', 'aria-live', 'polite');
    cy.get('[data-testid="password-error-message"]').should('have.attr', 'aria-live', 'polite');

    // Verify both error messages are associated with their respective inputs
    cy.get('[data-testid="email-input"]').should('have.attr', 'aria-describedby', '[data-testid="email-error-message"]');
    cy.get('[data-testid="password-input"]').should('have.attr', 'aria-describedby', '[data-testid="password-error-message"]');

    // Verify error messages are not hidden from screen readers
    cy.get('[data-testid="email-error-message"]').should('not.have.attr', 'hidden');
    cy.get('[data-testid="password-error-message"]').should('not.have.attr', 'hidden');
  });
});
